/*
 * prog17_whitespace_trim
 *
 * The original binary implements a tiny “whitespace‑trim” utility.
 * It reads the first command‑line argument (if any), limits the
 * processed length to 1024 characters, removes leading and trailing
 * whitespace, collapses any internal run of whitespace characters
 * to a single space, and prints the resulting string.
 *
 * Whitespace characters recognised by the original program are:
 *   ' ', '\t', '\n', '\r', '\v', '\f'
 *
 * If no argument is supplied, the argument is empty, or the result
 * after trimming is empty, the program prints the literal string
 * "EMPTY" (followed by a newline, as `puts` does).
 *
 * The implementation below reproduces exactly that observable
 * behaviour while being clear and idiomatic C.
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_INPUT 1024          /* same limit used by the original binary */

/* Return true if the character is one of the whitespace characters
   recognised by the original program. */
static bool is_ws(char c)
{
    return c == ' '  || c == '\t' || c == '\n' ||
           c == '\r' || c == '\v' || c == '\f';
}

/* Trim the input string according to the rules described above.
   The result is stored in `out`, which must be large enough to hold
   the transformed string (the same size as the input is sufficient). */
static void trim_whitespace(const char *in, char *out)
{
    size_t len = strlen(in);
    if (len > MAX_INPUT)               /* enforce the 1024‑byte limit */
        len = MAX_INPUT;

    size_t i = 0;          /* index in the input */
    size_t o = 0;          /* index in the output */
    bool have_output = false;   /* have we written any non‑whitespace yet? */
    bool last_was_ws = false;   /* was the previous processed char whitespace? */

    /* Skip leading whitespace */
    while (i < len && is_ws(in[i]))
        ++i;

    for ( ; i < len; ++i) {
        char c = in[i];
        if (is_ws(c)) {
            /* Remember that we saw whitespace; we will emit a single space
               later only if we already have output something. */
            last_was_ws = true;
        } else {
            /* If we just passed a run of whitespace and we already have
               some output, emit a single space before the current character. */
            if (last_was_ws && have_output) {
                out[o++] = ' ';
            }
            out[o++] = c;
            have_output = true;
            last_was_ws = false;
        }
    }

    out[o] = '\0';   /* null‑terminate the result */
}

/* Main entry point – reproduces the original program’s logic. */
int main(int argc, char *argv[])
{
    const char *input;
    char buffer[MAX_INPUT + 1];   /* +1 for the terminating NUL */

    if (argc < 2) {
        /* No argument supplied – the original program prints "EMPTY". */
        puts("EMPTY");
        return 0;
    }

    input = argv[1];
    trim_whitespace(input, buffer);

    if (buffer[0] == '\0') {
        /* Result is empty after trimming – also prints "EMPTY". */
        puts("EMPTY");
    } else {
        puts(buffer);
    }
    return 0;
}
